mapper.select:
select count(distinct cs.station_id) from charging_station cs left join charger c on cs.station_id = c.station_id where 1 = 1
and cs.address like concat('%', #{region}, '%')
and cs.station_status = #{stationStatus}
and c.charger_type = #{chargerType}
and cs.address like concat('%', #{keyword}, '%')
and cs.station_name like concat('%', #{keyword}, '%')

select cs.station_id as stationId , cs.station_name as stationName , cs.address as address , cs.station_status as stationStatus , count(c.charger_id) as chargerCount , count(c.charger_id) filter ( where c.status = '사용가능' ) as availableChargerCount , string_agg(distinct c.charger_type, ',') as chargerTypes from charging_station cs left join charger c on cs.station_id = c.station_id where 1 = 1
and cs.address like concat('%', #{region}, '%')
and cs.station_status = #{stationStatus}
and c.charger_type = #{chargerType}
and cs.address like concat('%', #{keyword}, '%')
and cs.station_name like concat('%', #{keyword}, '%')
group by cs.station_id , cs.station_name , cs.address , cs.station_status
order by cs.station_id desc
limit #{size} offset #{offset}

mapper.insert:

insert into charging_station (
      station_name
    , address
    , latitude
    , longitude
    , location
    , operator_name
    , open_time
    , close_time
    , station_status
    , created_at
) values (
      #{stationName}
    , #{address}
    , #{latitude}
    , #{longitude}
    , ST_SetSRID(ST_MakePoint(#{longitude}, #{latitude}), 4326)::geography
    , #{operatorName}
    , cast(#{openTime} as time)
    , cast(#{closeTime} as time)
    , #{stationStatus}
    , current_timestamp
)


insert into charger (
      station_id
    , charger_name
    , charger_type
    , connector_type
    , charging_speed_kw
    , price_per_kwh
    , status
    , created_at
) values (
      #{stationId}
    , #{charger.chargerName}
    , #{charger.chargerType}
    , #{charger.connectorType}
    , #{charger.chargingSpeedKw}
    , #{charger.pricePerKwh}
    , #{charger.status}
    , current_timestamp
)

mapper.update:

update charging_station
set
      station_name = #{stationName}
    , address = #{address}
    , latitude = #{latitude}
    , longitude = #{longitude}
    , location = ST_SetSRID(ST_MakePoint(#{longitude}, #{latitude}), 4326)::geography
    , operator_name = #{operatorName}
    , open_time = cast(#{openTime} as time)
    , close_time = cast(#{closeTime} as time)
    , station_status = #{stationStatus}
    , updated_at = current_timestamp
where station_id = #{stationId}


update charger
set
      charger_name = #{charger.chargerName}
    , charger_type = #{charger.chargerType}
    , connector_type = #{charger.connectorType}
    , charging_speed_kw = #{charger.chargingSpeedKw}
    , price_per_kwh = #{charger.pricePerKwh}
    , status = #{charger.status}
    , updated_at = current_timestamp
where station_id = #{stationId}
  and charger_id = #{charger.chargerId}

mapper.delete:

delete from charger c
where c.station_id = #{stationId}
  and c.charger_id = #{chargerId}
  and not exists (
      select 1
      from reservation r
      where r.charger_id = c.charger_id
  )
  and not exists (
      select 1
      from charging_session cs
      where cs.charger_id = c.charger_id
  )
